INSERT INTO public.products (name, slug, tagline, description, price_inr, unit, image_url, badge, stock, is_active, category_id) VALUES
('Jinlab Chirata Capsules', 'jinlab-chirata-capsules', 'Nature''s bitter power for complete wellness', 'Time-tested Himalayan herb known for its exceptional detoxifying and healing properties. Rich in natural bitters, Chirata is believed to help stimulate digestion, regulate blood sugar levels, support liver function and strengthen the immune system. Sourced sustainably and processed with care — free from chemicals, pesticides and artificial additives. 60 capsules, 500mg each.', 890, '60 caps', '/__l5e/assets-v1/96111091-3198-40df-b4c3-dfcc272da9d5/jinlab-p1.jpg', 'New', 40, true, 'c366cd79-b028-491f-9dbf-d7623c32b0bc'),
('Premium Multi Flora Honey', 'jinlab-premium-multi-flora-honey', 'Raw honey from native Apis cerana bees', 'Unprocessed multi-floral honey harvested from native Apis cerana bees foraging across Bhutan''s pristine highland meadows. Naturally crystallised, rich in enzymes and antioxidants. No heat treatment, no additives.', 650, '250 g', '/__l5e/assets-v1/69902103-0709-4c49-90eb-c25def89582f/jinlab-p2.jpg', 'Bestseller', 60, true, '1358c523-f65b-4e60-9107-1b6c090dbb9c'),
('Jinlab Avocado Jam', 'jinlab-avocado-jam', '60% pure avocado — homemade in Bhutan', 'Small-batch avocado jam made with 60% pure Bhutanese avocado. Silky, mildly sweet, and versatile — spread it on toast, swirl into yoghurt, or pair with cheese. A homemade product from a carbon-negative country.', 520, '220 g', '/__l5e/assets-v1/d58e515d-7697-431f-a9bf-dc36e30e3386/jinlab-p3.jpg', NULL, 45, true, '927213ae-1642-4249-9557-641cf93ef4fe'),
('Organic Turmeric Capsules', 'jinlab-organic-turmeric-capsules', 'Curcuma Longa — pure Bhutanese turmeric', 'High-curcumin organic turmeric capsules made from single-origin Bhutanese Curcuma Longa. Supports natural inflammation response, joint comfort and everyday immunity. Product of Bhutan — a carbon negative country.', 720, '60 caps', '/__l5e/assets-v1/8f7d95a4-5808-4d65-91ba-0545ad17eb5c/jinlab-p4.jpg', 'Organic', 55, true, 'c366cd79-b028-491f-9dbf-d7623c32b0bc'),
('Chirata Detox Capsules', 'jinlab-chirata-detox-capsules', 'The extra from the Himalayas', 'Premium Chirata detox blend in 500mg capsules — traditional Himalayan bitter herb prized for liver support and everyday detoxification. Made with care in Bhutan.', 990, '60 caps', '/__l5e/assets-v1/544ad295-4f46-49e9-9ac6-29142649771a/jinlab-p5.jpg', 'Premium', 30, true, 'c366cd79-b028-491f-9dbf-d7623c32b0bc'),
('Stingless-Bee Puthka Honey', 'jinlab-stingless-bee-puthka-honey', 'The most exotic honey of the Himalayas', 'Ultra-rare Puthka honey harvested from stingless bees native to Bhutan''s forests. Distinctly tangy, thin-bodied and famously prized in traditional wellness. A truly exotic product of a carbon-negative country.', 1450, '100 ml', '/__l5e/assets-v1/0ced81d6-b8fb-417e-b175-a5e56b1eb192/jinlab-p6.jpg', 'Rare', 20, true, '1358c523-f65b-4e60-9107-1b6c090dbb9c'),
('Natural Red Kiwi Jam', 'jinlab-natural-red-kiwi-jam', 'Homemade red kiwi jam from Bhutan', 'A rare, ruby-toned jam made from Bhutanese red kiwifruit. Bright, tart and lightly sweet — beautiful on scones, cheese boards or stirred into desserts. FSSAI certified.', 560, '220 g', '/__l5e/assets-v1/48b6c5ad-37f4-4486-80e3-8b1a620f66c5/jinlab-p7.jpg', NULL, 40, true, '927213ae-1642-4249-9557-641cf93ef4fe'),
('Pure Himalayan Bhutanese Shilajit', 'jinlab-bhutanese-shilajit', 'Pure resin from Bhutan''s high Himalayas', 'Hand-purified shilajit resin sourced from Bhutan''s high-altitude rock formations. Rich in fulvic acid and trace minerals — traditionally used to support stamina, vitality and recovery.', 1990, '20 g', '/__l5e/assets-v1/d70f3079-ae49-40f9-9f33-8fe9d3678e14/jinlab-p8.jpg', 'Premium', 25, true, 'c366cd79-b028-491f-9dbf-d7623c32b0bc'),
('Black Ginger Capsules', 'jinlab-black-ginger-capsules', 'Kaempferia Parviflora — Thai Ginseng of the Himalayas', 'Potent black ginger (Kaempferia Parviflora) capsules — traditionally used to support stamina, circulation and male vitality. Grown in Bhutan, a carbon-negative country.', 1150, '60 caps', '/__l5e/assets-v1/f361e676-207a-4c90-a0c7-7c83e194c8b4/jinlab-p9.jpg', NULL, 35, true, 'c366cd79-b028-491f-9dbf-d7623c32b0bc'),
('Organic Black Turmeric Capsules', 'jinlab-organic-black-turmeric-capsules', 'Cucurma Caesia — the rare black turmeric', 'Rare organic black turmeric (Cucurma Caesia) capsules — a prized Himalayan rhizome traditionally used for joint comfort, respiratory ease and antioxidant support. Product of Bhutan.', 1290, '60 caps', '/__l5e/assets-v1/37e20133-a801-43bd-8800-1f69405eeeff/jinlab-p10.jpg', 'Rare', 25, true, 'c366cd79-b028-491f-9dbf-d7623c32b0bc')
